		private LocalizedText ReadLocalizedText(Formatters.GameDataReader reader)
		{
			var locStringDictionary = default(List<KeyValuePair<string, string>>);
			reader.ReadObjectBegin();
			while(reader.Token != Formatters.ReaderToken.EndOfObject)
			{
				var key = reader.ReadMember();
				var value = reader.ReadAny()?.ToString();
				if (string.IsNullOrEmpty(key) ||
					string.IsNullOrEmpty(value) ||
					string.Equals(key, "notes", StringComparison.Ordinal))
				{
					continue;
				}

				if (locStringDictionary == null)
				{
					locStringDictionary = new List<KeyValuePair<string, string>>(10);
				}
				locStringDictionary.Add(new KeyValuePair<string, string>(key, value));
			}
			reader.ReadObjectEnd();

			if (locStringDictionary == null)
			{
				return LocalizedText.Empty;
			}
			else
			{
				return new LocalizedText(locStringDictionary, this.languageSwitcher);
			}
		}
		private DocumentReferenceCollection<DocumentT> ReadDocumentReferenceCollection<DocumentT>(Formatters.GameDataReader reader, string schemaIdOrName) where DocumentT : Document
		{
			if (reader.IsNull())
			{
				return DocumentReferenceCollection<DocumentT>.Empty;
			}

			var referenceCollection = default(List<DocumentReference<DocumentT>>);
			var isByIdCollection = reader.Token == Formatters.ReaderToken.BeginObject;

			if (isByIdCollection)
			{
				reader.ReadObjectBegin();
			}
			else
			{
				reader.ReadArrayBegin();
			}
			while (reader.Token != Formatters.ReaderToken.EndOfArray &&
					reader.Token != Formatters.ReaderToken.EndOfObject)
			{
				if (isByIdCollection)
				{
					var _ = reader.ReadMember(); // skip id
				}

				if (reader.IsNull())
				{
					reader.NextToken();
					continue;
				}

				var documentReference = this.ReadDocumentReference<DocumentT>(reader, schemaIdOrName);
				if (documentReference == null)
				{
					continue;
				}

				if (referenceCollection == null) { referenceCollection = new List<DocumentReference<DocumentT>>(5); }
				referenceCollection.Add(documentReference);
			}
			if (isByIdCollection)
			{
				reader.ReadObjectEnd();
			}
			else
			{
				reader.ReadArrayEnd();
			}
			if (referenceCollection == null)
			{
				return DocumentReferenceCollection<DocumentT>.Empty;
			}
			else
			{
				return new DocumentReferenceCollection<DocumentT>(referenceCollection);
			}
		}
		private DocumentReference<DocumentT> ReadDocumentReference<DocumentT>(Formatters.GameDataReader reader, string schemaIdOrName) where DocumentT : Document
		{
			var reference = default(DocumentReference<DocumentT>);
			reader.ReadObjectBegin();
			while (reader.Token != Formatters.ReaderToken.EndOfObject)
			{
				var key = reader.ReadMember();
				if (key == "Id")
				{
					reference = new DocumentReference<DocumentT>(reader.ReadAny(), schemaIdOrName, this.FindDocument);
				}
				else
				{
					reader.SkipAny();
				}
			}

			 // TODO maybe throw exception if reference is null (broken)?

			reader.ReadObjectEnd();
			return reference;
		}

