		public Formatters.IndexedDictionary<string, object> MergeGameData(IReadOnlyDictionary<string, object> gameDataDocument, IReadOnlyDictionary<string, object> patchDocument)
		{
			gameDataDocument.TryGetValue("Collections", out var gameDataCollectionsObj);
			var gameDataCollections = gameDataCollectionsObj as IReadOnlyDictionary<string, object> ?? new Formatters.IndexedDictionary<string,object>();
			patchDocument.TryGetValue("Collections", out var patchCollectionsObj);
			var patchCollections = patchCollectionsObj as IReadOnlyDictionary<string, object> ?? new Formatters.IndexedDictionary<string,object>();

			var newGameDataDocument = new Formatters.IndexedDictionary<string, object>(gameDataDocument);
			var newCollections = new Formatters.IndexedDictionary<string, object>(gameDataCollections);

			var visitedSchemas = new HashSet<string>(StringComparer.Ordinal);
			foreach (var schemaName in gameDataCollections.Keys.Concat(patchCollections.Keys))
			{
				if (visitedSchemas.Contains(schemaName)) {
					continue; // already has been visited
				}

				var gameDataDocumentCollection = default(object);
				var patchDocumentCollection = default(object);
#pragma warning disable 1522 // Empty switch block
				switch (schemaName)
				{
					case "18d4bf318f3c49688087dbed":
					case "Schema":
						visitedSchemas.Add("18d4bf318f3c49688087dbed");
						visitedSchemas.Add("Schema");

						if (!gameDataCollections.TryGetValue("18d4bf318f3c49688087dbed", out gameDataDocumentCollection)) {
							gameDataCollections.TryGetValue("Schema", out gameDataDocumentCollection);
						}
						if (!patchCollections.TryGetValue("18d4bf318f3c49688087dbed", out patchDocumentCollection)) {
							patchCollections.TryGetValue("Schema", out patchDocumentCollection);
						}

						if (gameDataDocumentCollection == null || patchDocumentCollection == null)
						{
							newCollections["Schema"] = gameDataDocumentCollection ?? patchDocumentCollection;
						}
						else
						{
							newCollections["Schema"] = MergeDocumentCollection<Schema>(gameDataDocumentCollection, patchDocumentCollection, purgeRest: false);
						}
						break;
					case "55a4f32faca22e191098f3d9":
					case "ProjectSettings":
						visitedSchemas.Add("55a4f32faca22e191098f3d9");
						visitedSchemas.Add("ProjectSettings");

						if (!gameDataCollections.TryGetValue("55a4f32faca22e191098f3d9", out gameDataDocumentCollection)) {
							gameDataCollections.TryGetValue("ProjectSettings", out gameDataDocumentCollection);
						}
						if (!patchCollections.TryGetValue("55a4f32faca22e191098f3d9", out patchDocumentCollection)) {
							patchCollections.TryGetValue("ProjectSettings", out patchDocumentCollection);
						}

						if (gameDataDocumentCollection == null || patchDocumentCollection == null)
						{
							newCollections["ProjectSettings"] = gameDataDocumentCollection ?? patchDocumentCollection;
						}
						else
						{
							newCollections["ProjectSettings"] = MergeDocumentCollection<ProjectSetting>(gameDataDocumentCollection, patchDocumentCollection, purgeRest: false);
						}
						break;
					case "d40d8eb1a23248b69b252eea":
					case "SchemaProperty":
						visitedSchemas.Add("d40d8eb1a23248b69b252eea");
						visitedSchemas.Add("SchemaProperty");

						if (!gameDataCollections.TryGetValue("d40d8eb1a23248b69b252eea", out gameDataDocumentCollection)) {
							gameDataCollections.TryGetValue("SchemaProperty", out gameDataDocumentCollection);
						}
						if (!patchCollections.TryGetValue("d40d8eb1a23248b69b252eea", out patchDocumentCollection)) {
							patchCollections.TryGetValue("SchemaProperty", out patchDocumentCollection);
						}

						if (gameDataDocumentCollection == null || patchDocumentCollection == null)
						{
							newCollections["SchemaProperty"] = gameDataDocumentCollection ?? patchDocumentCollection;
						}
						else
						{
							newCollections["SchemaProperty"] = MergeDocumentCollection<SchemaProperty>(gameDataDocumentCollection, patchDocumentCollection, purgeRest: false);
						}
						break;
				}
#pragma warning restore 1522

			}

			var changeNumber = 0;
			if (gameDataDocument.TryGetValue("ChangeNumber", out var gameDataChangeNumberObj) &&
				gameDataChangeNumberObj != null) {
				changeNumber = Convert.ToInt32(gameDataChangeNumberObj, CultureInfo.InvariantCulture);
			}
			if (patchDocument.TryGetValue("ChangeNumber", out var patchChangeNumberObj) &&
				patchChangeNumberObj != null) {
				changeNumber = Convert.ToInt32(patchChangeNumberObj, CultureInfo.InvariantCulture);
			}

			var revisionHash = default(string);
			if (gameDataDocument.TryGetValue("RevisionHash", out var gameDataRevisionHashObj) &&
				gameDataRevisionHashObj != null) {
				revisionHash = Convert.ToString(gameDataRevisionHashObj, CultureInfo.InvariantCulture);
			}
			if (patchDocument.TryGetValue("RevisionHash", out var patchRevisionHashObj) &&
				patchRevisionHashObj != null) {
				revisionHash = Convert.ToString(patchRevisionHashObj, CultureInfo.InvariantCulture);
			}

			newGameDataDocument["RevisionHash"] = revisionHash;
			newGameDataDocument["ChangeNumber"] = changeNumber;
			newGameDataDocument["Collections"] = newCollections;

			return newGameDataDocument;
		}

		public object MergeDocumentCollection<DocumentT>(object originalDocumentCollection, object modifiedDocumentCollection, bool purgeRest)
		{
			if (modifiedDocumentCollection == null && !purgeRest)
			{
				return Array.Empty<object>();
			}

			var originalCollectionById = ToDocumentsById(originalDocumentCollection);
			var modifiedCollectionById = ToDocumentsById(modifiedDocumentCollection);
			var mergedCollection = new Formatters.IndexedDictionary<string, object>(Math.Max(originalCollectionById.Count, modifiedCollectionById.Count) + 5);
			var documentIds = purgeRest ? modifiedCollectionById.Keys : originalCollectionById.Keys.Union(modifiedCollectionById.Keys);

			foreach (var documentId in documentIds)
			{
				var originalValueExists = originalCollectionById.TryGetValue(documentId, out var originalValue);
				var modifiedValueExists = modifiedCollectionById.TryGetValue(documentId, out var modifiedValue);

				object mergedDocument;
				if (originalValueExists && !modifiedValueExists)
				{
					// unchanged
					mergedDocument = originalValue;
				}
				else if (originalValueExists && originalValue == null)
				{
 					// keep deleted documents as deleted
					mergedDocument = null;
				}
				else if (!originalValueExists && modifiedValueExists)
				{
					// modified
					mergedDocument = modifiedValue;
				}
				else if (originalValue is IReadOnlyDictionary<string, object> originalValueDocument &&
						modifiedValue is IReadOnlyDictionary<string, object> modifiedValueDocument)
				{
					// merged
					mergedDocument = MergeDocument<DocumentT>(originalValueDocument, modifiedValueDocument);
				}
				else
				{
					// modified
					mergedDocument = modifiedValue;
				}

				mergedCollection[documentId] = mergedDocument;
			}
			return mergedCollection;
		}

		public object MergeDocument<DocumentT>(IReadOnlyDictionary<string, object> originalDocument, IReadOnlyDictionary<string, object> modifiedDocument)
		{
			var mergedDocument = new Formatters.IndexedDictionary<string, object>(Math.Max(originalDocument.Count, modifiedDocument.Count) + 5);

			if (typeof(DocumentT) == typeof(Schema))
			{
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Id");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Name");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "DisplayName");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Type");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Description");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "IdGenerator");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Specification");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Properties", (original, modified) => MergeDocumentCollection<SchemaProperty>(original, modified, purgeRest:true));
			}
			if (typeof(DocumentT) == typeof(ProjectSetting))
			{
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Id");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Name");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "PrimaryLanguage");
				MergePropertyLanguagesValue(mergedDocument, originalDocument, modifiedDocument, "Languages");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Copyright");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Version");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Extensions");
			}
			if (typeof(DocumentT) == typeof(SchemaProperty))
			{
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Id");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "SharedProperty");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Name");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "DisplayName");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Description");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "DataType");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "DefaultValue");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Uniqueness");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Requirement");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "ReferenceType");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Size");
				MergePropertyValue<object>(mergedDocument, originalDocument, modifiedDocument, "Specification");
			}
			return mergedDocument;
		}


		private static void MergePropertyDocumentValue<ValueT>(Formatters.IndexedDictionary<string, object> mergedDocument, IReadOnlyDictionary<string, object> originalDocument, IReadOnlyDictionary<string, object> modifiedDocument, string propertyName, Func<ValueT, ValueT, object> mergeFunc = null)
		{
